import{z as E,x as p,o,c as d,q as n,j as B,D as e,d as r,s as i,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"组提交","description":"","frontmatter":{"title":"组提交","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/group-commit.md","filePath":"cs/group-commit.md","lastUpdated":1791063341000}'),m={name:"cs/group-commit.md"};function A(c,a,f,u,h,C){const s=p("Mermaid");return o(),d("div",null,[a[2]||(a[2]=n('<h1 id="组提交" tabindex="-1">组提交 <a class="header-anchor" href="#组提交" aria-label="Permalink to &quot;组提交&quot;">​</a></h1><div class="epigraph"><p>许多事务的 commit 记录挤进同一次日志 fsync：延迟换吞吐，持久性不等式仍是「提交返回 ⇒ 日志已落」。</p><footer>—— 据 Gray and Reuter 组提交；Mohan；磁盘与 NVMe 上的 WAL</footer></div><p><a href="/cs/shadow-paging">上一课</a>对照切根。本课回到 WAL 路径的刷盘：每个提交都 <code>fsync</code> 则磁盘 IOPS 打满，吞吐上不去。组提交（group commit）把一个日志缓冲里的多个 commit 一起刷。持久性等级下一课把「刷到哪」再分级。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提交延迟 ≈ 等刷盘。组：领导者收集一个窗口内的提交者，一次 I/O，大家一起返回。缺口是<strong>窗口</strong>：等太久延迟差；不等则退化成每提交一刷。自适应窗口看队列长度。与并行：组提交是日志尾的串行点，是 OLTP 扩展上限之一——可分区日志缓解，复杂度高。</p><p>steal/no-force 仍成立：数据页不必在组里刷。只刷日志。</p><p><span class="marginnote">直觉类比：组提交像拼车去机场。一个人叫一趟车（一次 fsync）太贵；等一小段凑满一车人再出发，车费（I/O）大家平摊。等车的时间就是提交延迟，车开得越满、整体越省。</span></p><p><span class="marginnote">数字实例：设一次 fsync 耗 1 ms、盘的 IOPS 上限约 1000，逐笔刷盘的提交速率就卡在约 1000 TPS。若每 50 个 commit 拼一组，同样的 IOPS 就能支撑约 50 倍的提交带宽——吞吐换来的是最多一个窗口的等待；且这不是放松持久性，没赶上这一刷的事务会整体 abort，不会半提交。</span></p><p><span class="marginnote">Gray and Reuter。MySQL/Postgres 都有组提交实现。本课不调某个 <code>commit_delay</code> 参数表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>日志缓冲满或超时或 N 个 commit → flush。返回后事务可见（按隔离：提交可见性还要看锁释放点）。备库半同步后课会等备库 ACK，组提交窗口与复制 ACK 可叠。</p><p>崩溃：组里已刷的全提交，未进这次刷的全部 abort——原子的是这一刷。</p>',12)),(o(),B(l,null,{default:e(()=>[i(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22commit%22%5D%20--%3E%20BUF%5B%22%E6%97%A5%E5%BF%97%E5%B0%BE%E7%BC%93%E5%86%B2%22%5D%0A%20%20C2%5B%22commit%22%5D%20--%3E%20BUF%0A%20%20BUF%20--%3E%20FS%5B%22%E4%B8%80%E6%AC%A1%20fsync%22%5D%0A%20%20FS%20--%3E%20OK%5B%22%E6%95%B4%E7%BB%84%E8%BF%94%E5%9B%9E%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"与 TDE：加密日志页再刷，CPU 进组路径。与双写：数据页路径独立。校准：优化器不管组提交，但基准 TPC-C 对它极敏感——后课基准。",-1)),a[5]||(a[5]=t("p",null,"无组提交时，用户同步提交延迟=单次 fsync；SSD 仍有上限。",-1)),(o(),B(l,null,{default:e(()=>[i(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E4%BA%8B%E5%8A%A1%20A%20%E5%B7%B2%E8%BF%9B%E7%BB%84%22%5D%20--%3E%20FL%5B%22%E8%BF%99%E4%B8%80%E7%BB%84%20fsync%20%E8%90%BD%E7%9B%98%22%5D%0A%20%20T2%5B%22%E4%BA%8B%E5%8A%A1%20B%20%E5%B7%B2%E8%BF%9B%E7%BB%84%22%5D%20--%3E%20FL%0A%20%20T3%5B%22%E4%BA%8B%E5%8A%A1%20C%20%E8%BF%98%E5%9C%A8%E7%BC%93%E5%86%B2%22%5D%20--%3E%20NX%5B%22%E6%B2%A1%E8%B5%B6%E4%B8%8A%E8%BF%99%E4%B8%80%E5%88%B7%22%5D%0A%20%20FL%20--%3E%20A1%5B%22A%E3%80%81B%EF%BC%9A%E6%95%B4%E7%BB%84%E6%8F%90%E4%BA%A4%E8%BF%94%E5%9B%9E%22%5D%0A%20%20NX%20--%3E%20A2%5B%22C%EF%BC%9Aabort%EF%BC%8C%E9%87%8D%E6%8F%90%E4%BA%A4%22%5D%0A%20%20CR%5B%22%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20FL%0A%20%20CR%20--%3E%20NX%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">为什么重要：崩溃后数据库只认「最后一次成功的那一刷」这条线。线上的全部提交、线下的全部作废，没有中间态——判断边界的不是事务提交的先后，而是它有没有赶上这一次 I/O。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义 RPO 的全部等级。也不把组提交当 2PC。异步提交（先返回再刷）属于下一课耐久性放松。</p><p>后课默认：同步提交走组刷日志。持久性等级：同步、异步、备库参与。</p><p>组提交不改变 WAL 不等式，只改变每次 I/O 摊到多少事务。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多 commit 共享一次日志 fsync，吞吐升、尾延迟可能升。</li><li>崩溃原子单位是这一刷。</li><li>持久性等级下一课。</li><li>出处：Gray and Reuter；ARIES 实践。</li></ul>',7))])}const T=E(m,[["render",A]]);export{D as __pageData,T as default};
